from mechanism_design_context import add
add('halueval',10,'N','FACT','T','N','supported','consistent','none_identified',[( 'does not introduce any false or unsupported claims','target','is an Irish civil rights leader','The generic description is supported despite omitted name.')],'Treats supported but uninformative answer as non-hallucinated; no explicit neighbour use.')
add('halueval',11,'S','FACT','R','N','supported','consistent','none_identified',[( 'follows the same pattern of correctly identifying the winning team','neighbor','winning Oakland Raiders','Neighbour winner supported.'),('Denver Broncos defeated the Atlanta Falcons','target','The Broncos defeated the Falcons','Target winner supported.')],'Explicit same-pattern analogy grounded in each example\'s own evidence; different players/teams do not drive a contrasting classification.')
add('halueval',12,'C','FACT','R','N','supported','consistent','none_identified',[( 'unlike the reference example which invented a middle name','neighbor','Andrew Mark Bond','Neighbour substitutes James for Mark.'),('factually supported by the evidence','target','Hungarian goalkeeper Gábor Király','Separates missing-name incompleteness from false-name error.')],'Useful stated criterion distinction: absent specificity versus invented detail.')
add('halueval',13,'N','FACT','T','P','unsupported_inference','consistent','unsupported_target_inference',[( 'standard part of the tour\'s repertoire','target','during which they performed “Electrical Storm”','Target asserts an event during tour, not regular inclusion.'),('general performance capability throughout the tour','target','performed it on the second concert of their U2 360° Tour','One performance is enough for the target\'s existential claim.')],'Invents a throughout-tour/general-setlist implication; repeated elaboration ends mid-sentence but stance is assessable.','I')
add('halueval',14,'N','FACT','T','P','supported','consistent','uncertain',[( 'does not state that DJ Maphorisa collaborated','target','is a South African record producer and disk jockey','Evidence supplies identity but omits the collaboration relation.')],'Evidence-gap criticism is supported. External collaborator claim cannot be verified here, and naming featured artists would not exclude producer collaboration.')
add('halueval',15,'N','FACT','T','N','misreads_text','consistent','unsupported_target_inference',[( 'directly answers the question about what these institutions award','target','institutions which award what?','Question asks for award, not type of institution.'),('factually correct and fully supported','target','used to help visitors to navigate in large public buildings','The stated navigation fact remains supported.')],'Non-hallucination judgment is defensible, but claiming universities directly answers what they award misreads question. Incompleteness need not imply hallucination.')
add('halueval',16,'N','FACT','T','N','supported','consistent','none_identified',[( 'Geoffrey of Anjou and Matilda as the parents','target','Henry was the son of Geoffrey of Anjou and Matilda','Exact parentage supported.')],'Direct source check.')
add('halueval',17,'N','FACT','T','N','supported','consistent','none_identified',[( 'both Komondor and Portuguese Pointer are dog breeds','target','is a breed of dog developed as a gun dog','Answer supported; Komondor also explicitly a dog.')],'No neighbour transfer; correct broad classification.')
add('halueval',18,'N','FACT','T','N','supported','consistent','none_identified',[( 'reference example is irrelevant to the current classification','neighbor','Venice International Film Festival','Explicitly declines analogy to different example.'),('album was recorded in secret','target','The album was largely recorded in secret','Target evidence directly supports answer.')],'Explicitly rejects relevance of neighbour and judges own source; reference mention is not a used comparison.')
add('halueval',19,'C','FACT','R','N','supported','consistent','none_identified',[( 'reference example involved an unsupported claim','neighbor','Virgin Media UK','Neighbour supplies a name absent its Sky evidence.'),('base for Virgin Atlantic at Heathrow Terminal 3','target','It is also the base for Virgin Atlantic.','Correctly extracts named airline.')],'Distinguishes sourced name from unsupported name. Oneworld\'s terminal relation is omitted in evidence, but question supplies shared-terminal premise; does not overstate neighbour name.')
